/// <summary>
/// MPJ_28155_SalesFinalisation 3.6.1 Sales order shipment workbench
/// Handles the filter settings for the <c>METSalesOrderShipmentWorkbenchParameters</c> form.
/// </summary>
class METSalesOrderShipmentWorkbenchFilterParameters
{
    InventLocationId    inventLocationId;
    SalesShippingDate   shipDateFrom;
    SalesShippingDate   shipDateTo;
    METRoute            primaryRoute;
    CustAccount         custAccount;

    private static int CurrentVersion = 1;

    // A smart need to be built to default the warehouse value to the previous searched warehouse -this will ensure a default warehouse value is populated on the search parameter.
    #LOCALMACRO.CurrentList
        inventLocationId,
        shipDateFrom,
        shipDateTo,
        primaryRoute,
        custAccount
    #ENDMACRO

}

Method.Source:
public InventLocationId parmInventLocationId(InventLocationId _inventLocationId = inventLocationId)
{
    inventLocationId = _inventLocationId;
    return inventLocationId;
}

    public SalesShippingDate parmShipDateFrom(SalesShippingDate _shipDateFrom = shipDateFrom)
    {
        shipDateFrom = _shipDateFrom;

        if (!prmisDefault(_shipDateFrom))
        {
            if (shipDateFrom > shipDateTo && shipDateTo != dateNull())
            {
                shipDateTo = shipDateFrom;
            }
        }

        return shipDateFrom;
    }

    public SalesShippingDate parmShipDateTo(SalesShippingDate _shipDateTo = shipDateTo)
    {
        shipDateTo = _shipDateTo;

        if (!prmisDefault(_shipDateTo))
        {
            if (shipDateTo < shipDateFrom && shipDateTo != dateNull())
            {
                shipDateFrom = shipDateTo;
            }
        }

        return shipDateTo;
    }

public METRoute parmPrimaryRoute(METRoute _primaryRoute = primaryRoute)
{
    primaryRoute = _primaryRoute;
    return primaryRoute;
}

public CustAccount parmCustAccount(CustAccount _custAccount = custAccount)
{
    custAccount = _custAccount;
    return custAccount;
}

/// <summary>
///    Initializes a new instance of the <c>METSalesOrderShipmentWorkbenchParameters</c> class.
/// </summary>
/// <returns>
///    A new instance of the <c>METSalesOrderShipmentWorkbenchParameters</c> class.
/// </returns>
public static METSalesOrderShipmentWorkbenchFilterParameters construct()
{
    return new METSalesOrderShipmentWorkbenchFilterParameters();
}

    /// <summary>
    /// Loads the last values for the form name.
    /// </summary>
    /// <param name="_formName">
    /// The form name of the form.
    /// </param>
    /// <remarks>
    /// The default values are used if there is nothing to load.
    /// </remarks>
    public void loadLastValue(identifierName _formName)
    {
        container packedForm;
        Version version;

        packedForm = xSysLastValue::getValue(curext(), curUserId(), UtilElementType::Form, _formName);

        version = conpeek(packedForm, 1);

        if (version == CurrentVersion)
        {
            [version, #CurrentList] = packedForm;
        }
    }

/// <summary>
/// Saves the last values for the form name.
/// </summary>
/// <param name="_formName">
/// The form name of the form.
/// </param>
public void saveLastValue(identifierName _formName)
{
    xSysLastValue::putValue([CurrentVersion, #CurrentList], curext(), curUserId(), UtilElementType::Form, _formName);
}
